use std::io::{self, Read, Write};

/// Returns a borrowed view of the matching name, if there is one.
fn find_name<'a>(names: &'a [String], prefix: &str) -> Option<&'a String> {
    for n in names {
        if n.starts_with(prefix) {
            return Some(n);
        }
    }
    None
}

fn position_of(names: &[String], wanted: &str) -> Option<usize> {
    for (i, n) in names.iter().enumerate() {
        if n == wanted {
            return Some(i);
        }
    }
    None
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut it = input.split_whitespace();

    let n: usize = match it.next() {
        Some(t) => t.parse().unwrap(),
        None => return,
    };

    let mut names: Vec<String> = Vec::new();
    for _ in 0..n {
        names.push(it.next().unwrap().to_string());
    }

    let q: usize = it.next().unwrap().parse().unwrap();

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    for _ in 0..q {
        let token = it.next().unwrap();
        let query = if token == "_" { "" } else { token };

        match find_name(&names, query) {
            Some(found) => writeln!(out, "prefix {} {}", query, found).unwrap(),
            None => writeln!(out, "prefix {} none", query).unwrap(),
        }

        // if let, for when only one arm is interesting
        if let Some(i) = position_of(&names, query) {
            writeln!(out, "exact {} {}", query, i).unwrap();
        } else {
            writeln!(out, "exact {} none", query).unwrap();
        }

        // map turns Option<&String> into Option<usize> without unwrapping
        let len = find_name(&names, query).map(|s| s.len()).unwrap_or(0);
        writeln!(out, "len {} {}", query, len).unwrap();
    }

    io::stdout().flush().ok();
}
